export interface Api {
  /** Simulates a consumer loan. It validates the amount (RULE-001) and the term (RULE-002), determines the annual rate from the term (RULE-003), calculates the monthly installment with the French system rounded to 2 decimals HALF_UP (RULE-004), calculates the total to pay as installment x term (RULE-005) and saves the accepted simulation with a sequential number and timestamp (RULE-006). A rejected simulation is not saved. Called by the Calcular action of SCR-SIMULADOR, whose result is shown in SCR-RESULTADO. (rules RULE-001, RULE-002, RULE-003, RULE-004, RULE-005, RULE-006) */
  simulateLoan(request: SimulateLoanRequest): Promise<SimulateLoanResponse>
}

/** The client over fetch; `baseUrl` is where the backend runs (same origin by default). */
export function createApi(baseUrl = '', fetchImpl: typeof fetch = (input, init) => fetch(input, init)): Api {
