import { useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  Button,
  Alert,
  KeyBar,
} from '@nexti/ds';

const MSG_MONTO = 'El monto debe estar entre 1.000 y 50.000';
const MSG_PLAZO = 'El plazo debe estar entre 6 y 60 meses';

function parseMonto(raw: string): number | null {
  const v = raw.trim().replace(',', '.');
  if (!/^\d+(\.\d{1,2})?$/.test(v)) return null;
  return Number(v);
}

function validateMonto(raw: string): string {
  const n = parseMonto(raw);
  if (n === null || n < 1000 || n > 50000) return MSG_MONTO;
  return '';
}

function validatePlazo(raw: string): string {
  if (!/^\d+$/.test(raw.trim())) return MSG_PLAZO;
  const n = Number(raw);
  if (n < 6 || n > 60) return MSG_PLAZO;
  return '';
}

export default function Simulador({ navigate }: { navigate: (to: string) => void }) {
  const [monto, setMonto] = useState('');
  const [plazo, setPlazo] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const errorMonto = submitted ? validateMonto(monto) : '';
  const errorPlazo = submitted ? validatePlazo(plazo) : '';
  // Output field "mensaje_error": shows the first validation message
  const mensajeError = errorMonto || errorPlazo;

  const isEmpty = monto === '' && plazo === '';

  function calcular() {
    setSubmitted(true);
    if (validateMonto(monto) === '' && validatePlazo(plazo) === '') {
      navigate('SCR-RESULTADO');
    }
  }

  function onMontoChange(v: string) {
    // numeric input: digits and one decimal separator, max 12 characters
    const clean = v.replace(/[^\d.,]/g, '');
    const firstSep = clean.search(/[.,]/);
    const normalized =
      firstSep === -1
        ? clean
        : clean.slice(0, firstSep + 1) + clean.slice(firstSep + 1).replace(/[.,]/g, '');
    setMonto(normalized.slice(0, 12));
  }

  function onPlazoChange(v: string) {
    // integer input: digits only
    setPlazo(v.replace(/\D/g, '').slice(0, 2));
  }

  return (
    <Screen
      title="Simula tu crédito de consumo"
      code="SCR-SIMULADOR"
      keys={
        <KeyBar
          actions={[{ key: 'ENTER', label: 'Calcular', onPress: calcular, primary: true }]}
        />
      }
    >
      <div
        onKeyDown={(e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            calcular();
          }
        }}
      >
        <Stack>
          <Card
            title="Datos del crédito"
            actions={
              <Button variant="primary" shortcut="ENTER" onClick={calcular}>
                Calcular
              </Button>
            }
          >
            <Stack>
              {isEmpty && !submitted && (
                <Alert tone="info">
                  Ingresa el monto y el plazo que deseas para calcular tu crédito. Ambos datos son
                  obligatorios.
                </Alert>
              )}

              <Grid columns={2}>
                <div data-field="monto">
                  <TextField
                    label="Monto (USD)"
                    required
                    numeric
                    maxLength={12}
                    hint="Entre 1.000 y 50.000"
                    error={errorMonto || undefined}
                    value={monto}
                    onChange={onMontoChange}
                  />
                </div>

                <div data-field="plazo">
                  <TextField
                    label="Plazo (meses)"
                    required
                    numeric
                    maxLength={2}
                    hint="Entre 6 y 60 meses"
                    error={errorPlazo || undefined}
                    value={plazo}
                    onChange={onPlazoChange}
                  />
                </div>
              </Grid>

              <div data-field="mensaje_error" aria-live="polite">
                {mensajeError && <Alert tone="error">{mensajeError}</Alert>}
              </div>

              <Row>
                <Button variant="primary" shortcut="ENTER" onClick={calcular}>
                  Calcular
                </Button>
              </Row>
            </Stack>
          </Card>
        </Stack>
      </div>
    </Screen>
  );
}
