import { useState } from 'react'
import type { FormEvent } from 'react'
import { Screen, Card, Grid, Stack, TextField, Button, Alert } from '@nexti/ds'
import { ApiError } from '../api/client'
import type { ScreenProps } from './types'

const MSG_MONTO_REQUERIDO = 'El monto es obligatorio'
const MSG_PLAZO_REQUERIDO = 'El plazo es obligatorio'
const MSG_MONTO = 'El monto debe estar entre 1.000 y 50.000'
const MSG_PLAZO = 'El plazo debe estar entre 6 y 60 meses'
const MSG_GENERICO = 'No se pudo calcular la simulación. Intenta nuevamente.'

function parseMonto(raw: string): number | null {
  const v = raw.trim().replace(',', '.')
  if (!/^\d+(\.\d{1,2})?$/.test(v)) return null
  return Number(v)
}

function parsePlazo(raw: string): number | null {
  const v = raw.trim()
  if (!/^\d+$/.test(v)) return null
  return Number(v)
}

export default function SimuladorScreen({ api, navigate }: ScreenProps) {
  const [monto, setMonto] = useState('')
  const [plazo, setPlazo] = useState('')
  const [errorMonto, setErrorMonto] = useState('')
  const [errorPlazo, setErrorPlazo] = useState('')
  const [mensajeError, setMensajeError] = useState('')
  const [busy, setBusy] = useState(false)

  function onMontoChange(v: string) {
    const clean = v.replace(/[^\d.,]/g, '')
    const firstSep = clean.search(/[.,]/)
    setMonto(
      firstSep === -1
        ? clean
        : clean.slice(0, firstSep + 1) + clean.slice(firstSep + 1).replace(/[.,]/g, ''),
    )
  }

  function onPlazoChange(v: string) {
    setPlazo(v.replace(/\D/g, ''))
  }

  async function onSubmit(e: FormEvent) {
    e.preventDefault()
    if (busy) return

    // Required fields first: nothing is called if one is empty.
    const reqMonto = monto.trim() === '' ? MSG_MONTO_REQUERIDO : ''
    const reqPlazo = plazo.trim() === '' ? MSG_PLAZO_REQUERIDO : ''
    setErrorMonto(reqMonto)
    setErrorPlazo(reqPlazo)
    if (reqMonto || reqPlazo) {
      setMensajeError(reqMonto || reqPlazo)
      return
    }

    // Convert the texts of the fields to the types of the client.
    const montoNum = parseMonto(monto)
    const plazoNum = parsePlazo(plazo)
    const fmtMonto = montoNum === null ? MSG_MONTO : ''
    const fmtPlazo = plazoNum === null ? MSG_PLAZO : ''
    setErrorMonto(fmtMonto)
    setErrorPlazo(fmtPlazo)
    if (montoNum === null || plazoNum === null) {
      setMensajeError(fmtMonto || fmtPlazo)
      return
    }

    setMensajeError('')
    setBusy(true)
    try {
      await api.simulateLoan({ monto: montoNum, plazo: plazoNum })
      navigate('SCR-RESULTADO')
    } catch (err) {
      setMensajeError(err instanceof ApiError ? err.message : MSG_GENERICO)
    } finally {
      setBusy(false)
    }
  }

  return (
    <Screen title="Simula tu crédito de consumo">
      <form onSubmit={onSubmit} noValidate>
        <Stack>
          <Card title="Datos del crédito">
            <Stack>
              <Grid columns={2}>
                <div data-field="monto">
                  <TextField
                    label="Monto (USD)"
                    required
                    numeric
                    hint="Entre 1.000 y 50.000"
                    error={errorMonto || undefined}
                    value={monto}
                    onChange={onMontoChange}
                  />
                </div>

                <div data-field="plazo">
                  <TextField
                    label="Plazo (meses)"
                    required
                    numeric
                    hint="Entre 6 y 60 meses"
                    error={errorPlazo || undefined}
                    value={plazo}
                    onChange={onPlazoChange}
                  />
                </div>
              </Grid>

              <div data-field="mensaje_error" aria-live="polite">
                {mensajeError && <Alert tone="error">{mensajeError}</Alert>}
              </div>

              <Button type="submit" variant="primary" data-action="ENTER" disabled={busy}>
                Calcular
              </Button>
            </Stack>
          </Card>
        </Stack>
      </form>
    </Screen>
  )
}
